-- Function: public.fn_get_enrollment_application_by_id
-- Backup generated on 2026-10-25 20:33:16

CREATE OR REPLACE FUNCTION public.fn_get_enrollment_application_by_id(p_tenant_id uuid, p_application_id uuid)  RETURNS TABLE(id uuid, branch_id uuid, branch_name character varying, child_first_name character varying, child_last_name character varying, date_of_birth date, gender character varying, parent_guardian_name character varying, parent_email character varying, parent_phone character varying, target_classroom_id uuid, target_classroom_name character varying, desired_start_date date, schedule_type character varying, pipeline_stage character varying, tour_date timestamp with time zone, tuition_monthly_rate numeric, deposit_amount numeric, sibling_discount_percent numeric, registration_fee numeric, internal_notes text, child_id uuid, created_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          a.id,         a.branch_id,         b.name AS branch_name,         a.child_first_name,         a.child_last_name,         a.date_of_birth,         a.gender,         a.parent_guardian_name,         a.parent_email,         a.parent_phone,         a.target_classroom_id,         c.name AS target_classroom_name,         a.desired_start_date,         a.schedule_type,         a.pipeline_stage,         a.tour_date,         a.tuition_monthly_rate,         a.deposit_amount,         a.sibling_discount_percent,         a.registration_fee,         a.internal_notes,         a.child_id,         a.created_at     FROM enrollment_pipeline_applications a     LEFT JOIN branches b ON a.branch_id = b.id     LEFT JOIN classrooms c ON a.target_classroom_id = c.id     WHERE a.tenant_id = p_tenant_id AND a.id = p_application_id; $function$ ;
